#!/usr/bin/env bash
# Detect whether a command has a bash completion script generated by a known
# bridge.
#
# Usage: detect-bridge.sh <root> [--bash-completion <file>] [--dir <dir>]...
#
# Directory precedence, highest first:
#   1. --dir directories, in the order given
#   2. BASH_COMPLETION_USER_DIR/*/completions, else
#      ${XDG_DATA_HOME:-$HOME/.local/share}/bash-completion/completions
#   3. $HOMEBREW_PREFIX/etc/bash_completion.d
#   4. BASH_COMPLETION_COMPAT_DIR, else /etc/bash_completion.d, then
#      <prefix>/etc/bash_completion.d for every <prefix>/bin|sbin in PATH
#   5. the completions dir that pkg-config reports for bash-completion
#   6. <prefix>/share/bash-completion/completions for every <prefix>/bin|sbin in
#      PATH, for <root>'s own directory, and for its symlink target
#   7. XDG_DATA_DIRS/bash-completion/completions
#
# Compat dirs outrank completions dirs because bash-completion sources them at
# startup, before it lazily loads a per-command file; the Homebrew compat dir is
# searched first by local preference. Inside one directory set, a plain <root>
# file anywhere beats any _<root> fallback, mirroring bash-completion's loader.
# The first file that exists wins, even when it carries no bridge signature.
#
# The file must match the signature of a generated bash completion:
#   click       _<PROG>_COMPLETE=bash_complete + IFS=',' read type value
#   typer       _<PROG>_COMPLETE=complete_bash + COMPREPLY=( $( env ...
#   cobra       __complete / __completeNoDesc + shellCompDirective*
#   argcomplete _ARGCOMPLETE= + _python_argcomplete
#   clap        _CLAP_COMPLETE_INDEX= + _CLAP_IFS=
#   urfave      --generate-shell-completion + __<PROG>_bash_autocomplete
#   yargs       --get-yargs-completions + _<PROG>_yargs_completions
#
# Prints the bridge name (click, typer, cobra, argcomplete, clap, urfave, or
# yargs) when one matches and nothing otherwise.
#
# Exit status: 0 when a bridge matches, 1 when none matches, and 2 on usage
# errors.

set -euo pipefail

SCRIPT_DIR="$(cd -P "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
# shellcheck source=lib.sh
source "$SCRIPT_DIR/lib.sh"
require_cmd grep

usage() {
    cat <<'USAGE'
Usage: detect-bridge.sh <root> [options]

Scan the bash-completion lookup directories for <root>'s completion script and
print the bridge it was generated by: click, typer, cobra, argcomplete, clap,
urfave, or yargs. Nothing is printed when no known signature matches.

Precedence: --dir, user completions dir, Homebrew then distro compat dirs,
pkg-config completions dir, PATH-derived share dirs, XDG_DATA_DIRS.

Options:
  --bash-completion <file>  Inspect this file instead of scanning directories
  --dir <dir>               Add a completion directory to the search (repeatable)
  -h, --help                Show this help

Exit status: 0 when a bridge matches, 1 when none matches, 2 on usage errors.
USAGE
}

usage_die() {
    printf 'detect-bridge: %s\n' "$*" >&2
    exit 2
}

root=""
completion_override=""
extra_dirs=()

while [[ $# -gt 0 ]]; do
    case "$1" in
        -h|--help)
            usage
            exit 0
            ;;
        --bash-completion)
            [[ $# -ge 2 ]] || usage_die "$1 requires a value"
            completion_override="$2"
            shift 2
            ;;
        --dir)
            [[ $# -ge 2 ]] || usage_die "$1 requires a value"
            [[ -n "$2" ]] || usage_die "--dir requires a non-empty value"
            extra_dirs+=("$2")
            shift 2
            ;;
        -*)
            usage_die "unknown option: $1"
            ;;
        *)
            [[ -z "$root" ]] || usage_die "only one root command is supported"
            root="$1"
            shift
            ;;
    esac
done

[[ -n "$root" ]] || { usage >&2; exit 2; }
root_name_ok "$root" || usage_die "invalid root command name: $root"

declare -a search_dirs=()
declare -A seen_dirs=()

add_dir() {
    local dir="${1%/}"
    [[ -n "$dir" ]] || return 0
    [[ -n "${seen_dirs[$dir]:-}" ]] && return 0
    seen_dirs[$dir]=1
    search_dirs+=("$dir")
}

add_user_dirs() {
    local dir base
    local -a dirs=()
    if [[ -n "${BASH_COMPLETION_USER_DIR:-}" ]]; then
        IFS=: read -r -a dirs <<<"$BASH_COMPLETION_USER_DIR"
        for dir in "${dirs[@]}"; do
            if [[ -n "$dir" ]]; then
                add_dir "${dir%/}/completions"
            fi
        done
        return 0
    fi
    if [[ -n "${XDG_DATA_HOME:-}" ]]; then
        base="${XDG_DATA_HOME%/}"
    elif [[ -n "${HOME:-}" ]]; then
        base="${HOME%/}/.local/share"
    else
        base=""
    fi
    if [[ -n "$base" ]]; then
        add_dir "$base/bash-completion/completions"
    fi
    return 0
}

# add_bin_dir <dir>: a directory ending in bin/ or sbin also owns the
# share/bash-completion/completions directory beside it. The ?* guard keeps
# /bin and /sbin from expanding into a bogus /share path.
add_bin_dir() {
    local dir="${1%/}"
    case "$dir" in
        ?*/bin|?*/sbin) add_dir "${dir%/*}/share/bash-completion/completions" ;;
    esac
}

add_compat_bin_dir() {
    local dir="${1%/}"
    case "$dir" in
        ?*/bin|?*/sbin) add_dir "${dir%/*}/etc/bash_completion.d" ;;
    esac
}

# real_path <path>: follow a symlink chain without readlink -f, which macOS
# readlink lacks. Version managers and Nix profiles expose a launcher whose
# target owns the real completion directory.
real_path() {
    local path="$1" n=0 target
    while [[ -L "$path" ]]; do
        ((n++ < 16)) || break
        target="$(readlink "$path" 2>/dev/null || true)"
        [[ -n "$target" ]] || break
        [[ "$target" == /* ]] || target="$(dirname "$path")/$target"
        path="$target"
    done
    printf '%s\n' "$path"
}

add_path_dirs() {
    local dir path
    local -a paths=()
    IFS=: read -r -a paths <<<"${PATH:-}"
    for dir in "${paths[@]}"; do
        add_bin_dir "$dir"
    done
    if path="$(command -v "$root" 2>/dev/null)" && [[ "$path" == /* ]]; then
        add_bin_dir "${path%/*}"
        add_bin_dir "$(dirname "$(real_path "$path")")"
    fi
    if [[ -n "${HOMEBREW_PREFIX:-}" ]]; then
        add_dir "${HOMEBREW_PREFIX%/}/share/bash-completion/completions"
    fi
}

# Homebrew installs its compat completions next to the prefix. They are searched
# before the distro compat dirs but after the user completions dir.
add_homebrew_compat_dirs() {
    if [[ -n "${HOMEBREW_PREFIX:-}" ]]; then
        add_dir "${HOMEBREW_PREFIX%/}/etc/bash_completion.d"
    fi
}

add_compat_dirs() {
    local dir
    local -a paths=()
    if [[ -n "${BASH_COMPLETION_COMPAT_DIR:-}" ]]; then
        add_dir "${BASH_COMPLETION_COMPAT_DIR%/}"
    else
        add_dir "/etc/bash_completion.d"
    fi
    IFS=: read -r -a paths <<<"${PATH:-}"
    for dir in "${paths[@]}"; do
        add_compat_bin_dir "$dir"
    done
}

# pkg-config knows the completions dir of a prefixed bash-completion install
# that is neither beside a PATH bin dir nor under XDG_DATA_DIRS. It is optional:
# skip silently when pkg-config or the bash-completion metadata is missing.
add_pkgconfig_dirs() {
    local pkgconfig dir
    pkgconfig="$(command -v pkg-config 2>/dev/null || command -v pkgconf 2>/dev/null || true)"
    [[ -n "$pkgconfig" ]] || return 0
    dir="$("$pkgconfig" --variable=completionsdir bash-completion 2>/dev/null || true)"
    if [[ -n "$dir" ]]; then
        add_dir "$dir"
    fi
}

add_xdg_dirs() {
    local dir
    local -a dirs=()
    IFS=: read -r -a dirs <<<"${XDG_DATA_DIRS:-/usr/local/share:/usr/share}"
    for dir in "${dirs[@]}"; do
        [[ -n "$dir" ]] && add_dir "${dir%/}/bash-completion/completions"
    done
}

# Probe every directory for plain <root> before any directory's _<root>, then
# the .bash variants, mirroring bash-completion's loader: the name prefix is the
# outer loop, not the directory. The first existing file wins, so a plain file in
# a high-priority directory shadows a bridge script from a lower one.
find_completion_file() {
    local prefix dir suffix candidate
    for prefix in "" _; do
        for dir in "${search_dirs[@]}"; do
            for suffix in "" .bash; do
                candidate="$dir/$prefix$root$suffix"
                if [[ -f "$candidate" ]]; then
                    printf '%s\n' "$candidate"
                    return 0
                fi
            done
        done
    done
    return 1
}

# A Click-generated bash script asks for bash_complete and decodes the
# "type,value" records itself:
#   response=$(env ... _BLACK_COMPLETE=bash_complete ...)
#   IFS=',' read type value <<< "$completion"
is_click_completion() {
    grep -Eq '_[[:alnum:]_]+_COMPLETE=bash_complete([[:space:]]|$)' "$1" &&
        grep -Fq "IFS=',' read type value" "$1"
}

# A Typer-generated bash script uses Click's legacy instruction spelling and
# collects bare values:
#   _FASTAPI_COMPLETE=complete_bash
#   COMPREPLY=( $( env COMP_WORDS=... ) )
is_typer_completion() {
    grep -Eq '_[[:alnum:]_]+_COMPLETE=complete_bash([[:space:]]|$)' "$1" &&
        grep -Eq 'COMPREPLY=\([[:space:]]*\$\([[:space:]]*env[[:space:]]+COMP_WORDS=' "$1"
}

# A Cobra V2 bash script calls the program with __complete and decodes the
# shellCompDirective bitmask.
is_cobra_completion() {
    grep -Eq '__complete(NoDesc)?([[:space:]]|$)' "$1" &&
        grep -Eq 'shellCompDirective(Error|NoSpace|NoFileComp|FilterFileExt|FilterDirs|KeepOrder)' "$1"
}

# argcomplete wires the program into its _ARGCOMPLETE IPC protocol.
is_argcomplete_completion() {
    grep -Eq '_ARGCOMPLETE=' "$1" &&
        grep -Eq '(_python_argcomplete|__python_argcomplete)' "$1"
}

# A clap dynamic completion script forwards the current index and IFS through
# the _CLAP_* environment and calls the program with a `--` sentinel:
#   _CLAP_IFS="$IFS" _CLAP_COMPLETE_INDEX=${COMP_CWORD} ... prog -- "${words[@]}"
is_clap_completion() {
    grep -Eq '_CLAP_COMPLETE_INDEX=' "$1" &&
        grep -Eq '_CLAP_IFS=' "$1"
}

# An urfave/cli v3 bash script requests completions through the hidden
# --generate-shell-completion flag and returns token:description lines:
#   __<PROG>_build_completion_request / __<PROG>_bash_autocomplete
is_urfave_completion() {
    grep -Fq -- '--generate-shell-completion' "$1" &&
        grep -Eq '__[[:alnum:]_]+_(bash_autocomplete|build_completion_request)' "$1"
}

# A yargs bash script asks the program for candidates through the hidden
# --get-yargs-completions flag and wraps the call in _<PROG>_yargs_completions:
#   mapfile -t type_list < <(prog --get-yargs-completions "${args[@]}")
is_yargs_completion() {
    grep -Fq -- '--get-yargs-completions' "$1" &&
        grep -Eq '_[[:alnum:]_]+_yargs_completions' "$1"
}

detect_bridge() {
    local file="$1" bridge
    for bridge in click typer cobra argcomplete clap urfave yargs; do
        if "is_${bridge}_completion" "$file"; then
            printf '%s\n' "$bridge"
            return 0
        fi
    done
    return 1
}

completion_file=""
if [[ -n "$completion_override" ]]; then
    completion_file="$(absolute_path "$completion_override")"
    [[ -f "$completion_file" ]] || usage_die "bash completion file not found: $completion_file"
else
    for dir in "${extra_dirs[@]}"; do
        add_dir "$dir"
    done
    add_user_dirs
    add_homebrew_compat_dirs
    add_compat_dirs
    add_pkgconfig_dirs
    add_path_dirs
    add_xdg_dirs
    if completion_file="$(find_completion_file)"; then
        :
    else
        completion_file=""
    fi
fi

if [[ -n "$completion_file" ]]; then
    if bridge="$(detect_bridge "$completion_file")"; then
        printf '%s\n' "$bridge"
        exit 0
    fi
fi
exit 1
